from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable


DISCOUNT_RATES = {
    "SAVE10": 0.10,
    "SAVE20": 0.20,
}


@dataclass(frozen=True)
class CartItem:
    sku: str
    unit_price: float
    quantity: int = 1


def _line_total(item: CartItem) -> float:
    if item.quantity < 0:
        raise ValueError("quantity cannot be negative")
    if item.unit_price < 0:
        raise ValueError("unit_price cannot be negative")
    return item.unit_price * item.quantity


def calculate_total(
    items: Iterable[CartItem],
    discount_code: str | None = None,
    tax_rate: float = 0.0,
) -> float:
    if tax_rate < 0:
        raise ValueError("tax_rate cannot be negative")

    subtotal = sum(_line_total(item) for item in items)
    normalized_code = (discount_code or "").strip().upper()
    discount_rate = DISCOUNT_RATES.get(normalized_code, 0.0)

    # Apply discount BEFORE tax — US sales tax is computed on the amount the
    # customer actually pays (post-discount), not the gross subtotal.
    discounted_subtotal = subtotal * (1 - discount_rate)
    tax_amount = discounted_subtotal * tax_rate
    total = discounted_subtotal + tax_amount

    return round(total, 2)

